1	import { forwardRef, type InputHTMLAttributes } from 'react';
2	import { cn } from '../../utils/cn';
3	import { ButtonText } from '../Text';
4	import { HotkeyIndicator } from '../HotkeyIndicator/HotkeyIndicator';
5	import { IconSize, SearchIcon } from '../Icons';
6	
7	export interface SearchBoxProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> {
8	  /** Keyboard shortcut keys displayed on the right. E.g. ['⌘', 'K'] or ['Ctrl', 'k']. */
9	  shortcut?: string[];
10	  /** Whether the hotkey indicator is shown. Defaults to true when shortcut is provided. */
11	  showShortcut?: boolean;
12	}
13	
14	/**
15	 * A search input field styled per the design system.
16	 * Larger corner radius (rounded-soft) and leading search icon distinguish it from Input.
17	 * Accepts an optional keyboard shortcut indicator on the trailing edge.
18	 * Twin of `DropdownMenuSearch` (same icon + input + hotkey row, no menu): apply row fixes to both.
19	 * `className` styles the bordered field `<div>`; `ref`, `style` and every other prop go to the `<input>`.
20	 *
21	 * @example
22	 * <SearchBox placeholder="Search..." shortcut={['⌘', 'K']} />
23	 */
24	const SearchBox = forwardRef<HTMLInputElement, SearchBoxProps>(
25	  ({ className, shortcut, showShortcut = !!shortcut, placeholder = 'Search', disabled, ...props }, ref) => {
26	    return (
27	      <div
28	        data-disabled={disabled ? '' : undefined}
29	        className={cn(
30	          'flex items-center gap-sm',
31	          'bg-secondary border border-solid border-border-primary',
32	          'rounded-soft',
33	          'pl-lg pr-md py-md',
34	          'ds-min-w-search-box',
35	          'ds-motion-state',
36	          '[&:not([data-disabled])]:hover:border-input-border-hover',
37	          'focus-within:border-input-border-focus ds-focus-within-ring',
38	          'ds-radix-data-disabled data-[disabled]:bg-secondary-disabled data-[disabled]:border-secondary-border-disabled',
39	          className
40	        )}
41	      >
42	        {/* Search icon — the DS glyph, the same one DropdownMenuSearch draws */}
43	        <SearchIcon size={IconSize.md} className="shrink-0 text-text-tertiary" />
44	
45	        {/* Native input */}
46	        <ButtonText
47	          as="input"
48	          ref={ref}
49	          placeholder={placeholder}
50	          disabled={disabled}
51	          className={cn(
52	            'flex-1 min-w-0 bg-transparent outline-none',
53	            'text-text placeholder:text-text-tertiary',
54	          )}
55	          {...props}
56	        />
57	
58	        {/* Keyboard shortcut hint */}
59	        {showShortcut && shortcut && shortcut.length > 0 && (
60	          <HotkeyIndicator keys={shortcut} className="shrink-0" />
61	        )}
62	      </div>
63	    );
64	  }
65	);
66	
67	SearchBox.displayName = 'SearchBox';
68	
69	export { SearchBox };
